<?php namespace App\Livewire\Admin; use App\Models\User; use Illuminate\Support\Facades\Hash; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class ManageUsers extends Component { public string $name = ''; public string $email = ''; public string $password = 'password'; public string $role = 'vendor'; public function createUser(): void { $validated = $this->validate(['name' => ['required', 'string', 'max:255'], 'email' => ['required', 'email', 'unique:users,email'], 'password' => ['required', 'string', 'min:6'], 'role' => ['required', 'in:student,vendor,admin']]); User::create(['name' => strip_tags($validated['name']), 'email' => $validated['email'], 'password' => Hash::make($validated['password']), 'role' => $validated['role']]); $this->reset(['name', 'email']); session()->flash('status', 'User account created.'); } public function render() { return view('livewire.admin.manage-users', ['users' => User::latest()->get()]); } }